<script setup>
import {ref,onMounted} from 'vue'
import {request} from './client'
import ActionNotice from './ActionNotice.vue'
const data=ref(null),busy=ref(false),error=ref(''),site=ref(''),start=ref(''),end=ref(''),page=ref(0)
const money=(value,currency)=>new Intl.NumberFormat('en-LK',{style:'currency',currency:currency||'LKR'}).format(Number(value||0)/100)
async function load(reset=false){if(busy.value)return;if(reset)page.value=0;busy.value=true;error.value='';try{const result=await request('owner_operations','billing',{site:site.value||'',start:start.value||'',end:end.value||'',page:page.value},'GET');data.value=result;site.value=result.site||'';start.value=result.start||'';end.value=result.end||''}catch(e){error.value=e.message;data.value=null}finally{busy.value=false}}
onMounted(()=>load())
</script>
<template><section class="owner-billing"><ActionNotice :message="error" :failure="true"/><h2>Provider subscriptions & invoices</h2><p>Review the plans and invoices used by independent teachers and institutes. Student bank transfers belong to the receiving teacher or institute and are reviewed in their Class fees page.</p><form @submit.prevent="load(true)" class="filters"><label>Campus<select v-model="site" :disabled="busy"><option v-for="s in data?.sites||[]" :key="s" :value="s">{{s}}</option></select></label><label>From<input type="date" v-model="start"></label><label>Through<input type="date" v-model="end"></label><button class="button primary" :disabled="busy">{{busy?'Loading…':'Apply dates & refresh'}}</button></form><p v-if="error" role="alert">{{error}}</p><template v-if="data"><p v-if="!data.configured">The hosting operator needs to connect campus reporting before billing records can be displayed.</p><template v-else><h3>Current provider accounts</h3><p>Account counts show registration status, not proof of an active paid subscription.</p><div class="summary"><article v-for="s in data.subscriptions" :key="s.plan" class="panel"><strong>{{s.plan}}</strong><p>{{s.accounts}} accounts · {{s.enabled_accounts}} enabled</p></article></div><h3>Invoices created in this date range</h3><div class="summary"><article v-for="t in data.totals" :key="t.currency+t.status" class="panel"><strong>{{t.status}} · {{t.currency}}</strong><p>{{money(t.amount_minor,t.currency)}} · {{t.invoices}} invoices</p></article></div><p v-if="!data.rows.length">No provider invoices in this date range.</p><div v-else class="scroll"><table><thead><tr><th>Provider / invoice</th><th>Plan</th><th>Amount</th><th>Status</th><th>Billing period</th><th>Receipt</th></tr></thead><tbody><tr v-for="r in data.rows" :key="r.name"><td>{{r.billed_to}}<small>{{r.name}}</small></td><td>{{r.plan}}</td><td>{{money(r.amount_minor,r.currency)}}</td><td>{{r.status}}<small v-if="r.paid_at">Paid {{r.paid_at}}</small></td><td>{{r.period_start}} – {{r.period_end}}</td><td>{{r.receipt_number||'—'}}</td></tr></tbody></table></div><nav v-if="page||data.has_next"><button class="button subtle" :disabled="busy||!page" @click="page--;load()">Previous</button><button class="button subtle" :disabled="busy||!data.has_next" @click="page++;load()">Next</button></nav><p>This report does not charge customers or mark invoices paid. Only the payment verification workflow can confirm settlement.</p></template></template></section></template>
<style scoped>.filters{display:flex;flex-wrap:wrap;gap:16px;align-items:end;margin:24px 0}label{display:grid;gap:8px}input,select{font:inherit;padding:10px;border:1px solid #ddd;border-radius:8px;max-width:100%}.summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px}.panel{padding:20px}.scroll{overflow:auto}small{display:block}.owner-billing p{line-height:1.65}nav{display:flex;gap:10px;margin-top:16px}</style>
<style scoped>table{min-width:760px}td{overflow-wrap:anywhere;max-width:220px}.filters input,.filters select{background:var(--surface,#fff);color:inherit}</style>
